function renderTop(){return `<header class="topbar"><div class="brand"><div class="brandmark">${ic('scan')}</div><h1>供包工作台</h1><span class="brand-sub">SPORTMASTER</span><span class="rule"></span><b class="mono">${F.station}</b><span class="hint">${F.floor}</span></div><nav class="topnav" aria-label="辅助功能">${btn('作业记录','records','ghost',false,'history')}${btn('报警'+(activeAlarm()?' · 1':''),'alarms','ghost',false,'bell')}${btn('设备与设置','settings','ghost',false,'settings')}${btn(s.session==='Paused'?'恢复入场':'暂停入场',s.session==='Paused'?'resume':'pause','ghost',!['Active','Paused'].includes(s.session),s.session==='Paused'?'play':'pause')}<div class="user"><span class="avatar">${s.auth==='ApprovedSkip'?'免':'李'}</span><span>${s.auth==='ApprovedSkip'?'已配置跳过登录':s.role==='maintenance'?'维护员 · 授权样例':'李明 · 操作员'}</span>${btn('登出','logout','ghost small')}</div></nav></header><div class="health">${conn(s.camera[0],'CAM0')}${conn(s.camera[1],'CAM1')}<span class="rule"></span>${conn(s.wcs,'WCS')}<span class="connection ${s.store?'ok-text':'error-text'}">${ic('server')}本地存储 · ${s.store?'可写':'写入失败'}</span><span class="freshness">${s.camera[0]!=='Ready'||s.wcs!=='Ready'?'旧状态已失效 · 最后确认 14:31:12':'模拟快照 · 最后更新 '+F.now}</span></div>`;}
function tote(){if(!active())return `<section class="tote"><div class="row" style="min-width:210px">${ic('box','lg')}<div><div class="label">共享周转箱</div><b style="font-size:20px">${s.session==='ValidatingTote'?'周转箱校验中':'请扫描周转箱'}</b></div></div><form id="tote-form" class="tote-entry"><input id="tote-input" aria-label="周转箱条码" autocomplete="off" placeholder="扫码枪输入周转箱条码" value="${esc(s.toteInput)}" ${s.session==='ValidatingTote'?'disabled':''} ${s.session==='ToteRejected'?'aria-invalid="true"':''}><button class="primary" type="submit" ${s.session==='ValidatingTote'?'disabled':''}>${s.session==='ValidatingTote'?'正在校验':'校验周转箱'}</button><span class="hint ${s.session==='ToteRejected'?'error-text':''}">${s.session==='ToteRejected'?'拦截，非本层箱。请核对并重扫。':'先验箱，再处理Item；不会自动发车。'}</span></form>${btn('结束供包','end','tote-end',true)}</section>`;const label={Active:'已校验',Paused:'入场暂停',Recovering:'恢复核对中',ClosingCheck:'正在核对',AwaitingShortageDecision:'待少货确认',Closing:'结束处理中',CloseUnknown:'结束待核对'}[s.session];return `<section class="tote"><div class="tote-main"><div class="row"><span class="label">当前周转箱</span>${chip(label,s.session==='Active'?'ok':'warn')}</div><div class="tote-code">${F.tote}</div></div><div class="tote-wave"><div class="label">所属波次 <span class="hint">· WCS已校验</span></div><div class="wave-code">${F.wave}</div></div><div class="tote-count"><div class="label">本箱 WCS已接受</div><b>${total()}</b><span class="unit">件</span></div>${btn(s.session==='CloseUnknown'?'查看结束核对':'结束供包','end','tote-end',!['Active','CloseUnknown'].includes(s.session),'stop')}</section>`;}
function guidance(){let title='作业进行中',text='按通道提示处理Item；右通道需人工确认。',tone='',tail='共享箱 · 左右通道独立显示';if(!active()){title='等待周转箱校验';text='先扫描正确周转箱；两个通道不会生成可执行供包任务。';}else if(!s.store){title='整台暂停 · 本地记录未保存';text='新请求不会发送。保留现场Item，联系维护人员检查存储。';tone='error';}else if(s.camera[0]!=='Ready'){title=s.camera[0]==='Reconnecting'?'CAM0正在重连 · 尚未就绪':'CAM0连接中断 · 整台暂停新入场';text='请勿继续放货；恢复前核对当前Item与设备状态。';tone='error';tail='单侧降级待确认';}else if(s.wcs!=='Ready'){title='WCS不可用 · 暂停新入场';text='保留当前箱与Item；已发请求先核对，不批量重发。';tone='warn';}else if(s.session==='CloseUnknown'){title='周转箱结束结果待核对';text='请勿扫描新箱，也不要继续当前箱供包。等待WCS明确关闭结果。';tone='warn';}else if(s.lanes.some(l=>l.state==='OutcomeUnknown')){title='结果待核对 · 请勿重复放货';text='WCS可能已处理当前请求；本箱新入场暂不开放。';tone='warn';tail='不等于业务失败';}else if(s.scene==='agvWait'){title='AGV状态未取得 · 禁止新入场';text='尚无可靠就位及装载许可，请等待权威反馈。';tone='warn';}else if(s.session==='Paused'){title=s.scene==='recovered'?'恢复核对完成 · 待恢复入场':'软件已暂停新入场';text='已有WCS请求不会被撤销；软件暂停不是安全急停。';tone='warn';}else if(['Closing','ClosingCheck','AwaitingShortageDecision'].includes(s.session)){title='结束供包检查中';text='两通道暂停新入场；WCS明确关闭后才能切换箱。';tone='warn';}else if(s.demoSplit){title='拆包交互样例 · 方案待确认';text='仅演示扫描保留件候选，不代表D-04已批准。';tone='warn';tail='30 − 18 = 12件';}else if(s.lanes[1].state==='Rejected'){title='CAM1业务拦截';text='按右通道原因处理当前Item；不得跳过校验或反复发车。';tone='warn';}else if(s.lanes[1].state==='InvalidRead'){title='CAM1识别异常';text='调整条码与摆放后受控重扫，不允许人工改码放行。';tone='warn';}else if(s.lanes[1].state==='Accepted'){title='WCS已接受本次请求';text='遵循现场复位流程；没有反馈时不显示实体已完成。';}else if(s.lanes[1].state==='DispatchPending'){title='WCS处理中';text='已有请求在途，请勿重复操作。';}return `<div class="guidance-wrap"><div class="guidance ${tone}" role="status">${ic(tone?'warn':'info')}<div><strong>${title}</strong>${text}</div><span class="guide-tail">${tail}</span></div></div>`;}
function actionInfo(l){if(l.id===0&&s.camera[0]!=='Ready')return['查看连接诊断','settings','设备未就绪','不开放新入场；单侧降级尚未批准。',false,''];if(l.state==='Accepted')return['查看作业详情','detail:'+l.operation,'当前作业已接受','等待现场复位；本次不可再次发车。',false,''];if(l.state==='OutcomeUnknown')return['查看待核对','detail:'+l.operation,'禁止重复发车','只读核对；真实查询能力尚未确认。',false,''];if(l.state==='Rejected')return['查看拒绝详情','detail:'+l.operation,'按原因纠正后重新识别','不提供强制放行或无条件重试。',false,''];if(l.state==='InvalidRead')return['清空重扫','clear:'+l.id,'本次无可执行任务','只影响当前草稿，不删除历史。',!canClear(l),''];if(l.state==='UnpackRequired')return['确认拆包','noop','D-04未确认，禁止操作','保留量、移除量及扫描方向须先批准。',true,''];if(['UnpackCounting','AwaitingUnpackConfirm'].includes(l.state))return['确认拆包','splitConfirm:'+l.id,l.count===18?'计数达标 · 请核对实物':'有效扫描尚未达到目标',`保留18件 / 移除12件 · ${l.count}/18件（候选）`,l.count!==18||!s.gate,'primary'];if(['DispatchPending','DispatchQueued','Validating'].includes(l.state))return['查看处理详情','detail:'+l.operation,'已有请求正在处理','保留同一业务身份，不生成第二次供包。',false,''];if(l.state==='ReadyForAutoDispatch')return['等待自动条件','noop','无需点击发车','未取得真实联锁；许可仅能从评审台注入。',true,''];if(['Observed','Idle'].includes(l.state))return['手动发车','noop','暂无可提交的Item','请先完成识别与WCS校验。',true,''];return['手动发车','dispatch:'+l.id,s.gate?`本次供给${l.supply}件 · 目标格口${l.slot}`:'新入场已暂停',s.gate?(s.demoSplit?'拆包候选方案（D-04），尚未批准。':'不足量人工分支为评审候选（D-03）。'):'请先解除阻塞，不覆盖当前业务结果。',!permitted(l),'primary'];}
function lane(l){const[tone,title,desc,icon]=status(l),a=actionInfo(l),split=['UnpackRequired','UnpackCounting','AwaitingUnpackConfirm'].includes(l.state);let body=l.state==='Idle'?`<div class="blank">${ic('scan')}<h3>${active()?'等待有效Item入场':'请先扫描周转箱'}</h3><p>${active()?'相机自动读码并按来源进入本通道；不从全局键盘焦点推断。':'周转箱通过WCS校验后，才能进入Item作业。'}</p></div>`:`<div class="barcode-row"><div class="barcode-data"><div class="barcode-caption"><span class="label">Item条码</span><span class="hint">来源 CAM${l.id} · ${l.time}</span></div><div class="barcode">${esc(l.barcode)}</div></div>${btn('','copy:'+l.id,'icon-btn',l.barcode==='—','copy','aria-label="复制完整Item条码"')}</div>${l.readError==='multi'?'<div class="notice error">另一个候选码：<span class="mono">06902827041372</span><br>未选择任何码，不创建发车请求。</div>':''}<div class="meta-grid"><div><div class="label">SKU</div><div class="meta-value mono">${l.sku}</div></div><div><div class="label">分拨任务ID</div><div class="meta-value mono">${l.task}</div></div><div><div class="label">目标格口</div><div class="slot">${l.slot}</div></div></div><div class="item-wave"><span>Item关联波次</span><span class="mono">${l.wave}</span>${l.wave!=='—'&&l.wave!==F.wave?'<b class="error-text">与当前箱不一致</b>':''}</div><div class="quantity-grid">${[['包装内SKU数量',l.p],['剩余需求数量',l.d],[split?'需移除数量':'本次供给数量',split?l.p-l.d:l.supply]].map(([n,v],i)=>`<div class="quantity ${i===2&&v!==null?'accent':''}"><div class="label">${n}</div><span class="quantity-number">${v??'—'}</span><span class="unit">件</span></div>`).join('')}</div>${split?(s.demoSplit?`<div class="row between"><span class="label">有效扫描 / 保留件目标</span>${btn('清空重扫','clear:'+l.id,'small',false,'refresh')}</div><div class="row"><div class="progress-track"><div class="progress-fill" style="width:${l.count/18*100}%"></div></div><span class="count-value">${l.count} <span class="muted">/18</span></span></div><div class="split-warning">候选方案：保留18件、移除12件；当前计数v${l.revision}。D-04未批准，生产禁用。</div>`:'<div class="notice warn">数量关系：30 − 18 = 12件。扫描移除件还是保留件尚未确认，不填入虚假的有效计数。</div>'):''}`;
return `<article class="lane" id="lane${l.id}" aria-label="CAM${l.id}通道"><div class="lane-header"><div class="row"><span class="lane-number">0${l.id+1}</span><span class="lane-title">CAM${l.id} · ${l.id?'右':'左'}通道</span></div><span class="hint">${s.camera[l.id]==='Ready'?'相机自动识别 · 只读结果':'设备状态未就绪'}</span></div><div class="lane-result ${tone}"><div class="result-icon">${ic(icon,'lg')}</div><div style="min-width:0"><div class="result-title">${title}</div><div class="result-desc">${esc(desc)}</div></div>${l.state==='Accepted'&&s.camera[l.id]==='Ready'?`<div class="result-side"><strong>${l.supply}</strong><span>WCS接受 / 件</span></div>`:''}</div><div class="lane-body">${body}</div><div class="lane-action"><div class="action-explanation"><strong>${a[2]}</strong><small>${a[3]}</small></div>${btn(a[0],a[1],'action-btn '+a[5],a[4],a[5]?'arrow':'')}</div></article>`;}
function badge(v){return chip(({Accepted:'WCS已接受',Rejected:'已拒绝',OutcomeUnknown:'待核对',DispatchQueued:'待发送',DispatchPending:'处理中'})[v]||'待校验',({Accepted:'ok',Rejected:'error',OutcomeUnknown:'warn',DispatchQueued:'warn',DispatchPending:'blue'})[v]);}
function rows(rs,compact=false){return rs.map(r=>`<tr><td class="mono">${r.time}</td><td>CAM${r.channel}</td><td class="mono">${esc(r.barcode)}</td>${compact?'':`<td class="mono">${r.id}</td>`}<td>${r.slot}</td><td class="num">${r.state==='Accepted'?r.quantity:'—'}</td><td>${badge(r.state)}</td>${compact?'':`<td class="num">${r.attempts}</td>`}<td>${btn('详情','detail:'+r.id,'ghost small')}</td></tr>`).join('');}
function recent(){return `<section class="recent"><div class="recent-box"><div class="recent-head"><div class="row"><h2>最近作业</h2><span class="hint">一次作业一条记录；发送尝试见详情</span></div>${btn('查看全部 '+s.records.length+' 条','records','ghost',false,'chevron')}</div><table class="table"><thead><tr><th>时间</th><th>通道</th><th>Item条码</th><th>目标格口</th><th>WCS接受 / 件</th><th>处理结果</th><th>追溯</th></tr></thead><tbody>${rows(s.records.slice(0,2),true)}</tbody></table></div></section>`;}
function demo(){return `<div class="demo-bar" aria-label="评审控制台"><span class="demo-label">▷ 交互评审</span><label for="scene">状态</label><select id="scene">${SCENES.map(([v,t])=>`<option value="${v}" ${s.scene===v?'selected':''}>${t}</option>`).join('')}</select>${btn('模拟相机读码','demoRead')}${s.demoSplit?btn('模拟一件 · +1','demoCount'):s.scene==='unknown'?btn('注入核对：已接受','demoResolve'):s.scene==='auto'?btn('注入模拟许可','demoPermit'):['reconnecting','recovering'].includes(s.scene)?btn('注入恢复完成','demoRecover'):btn('重置场景','reset')}<span class="demo-note">示例数据 · 未连接相机 / WCS / 实体设备</span></div>`;}
function render(){if(innerWidth<1280||innerHeight<680){s.viewportPaused=true;s.gate=false;}$('#app').innerHTML=`<div class="app">${renderTop()}${tote()}${guidance()}<main class="lanes">${s.lanes.map(lane).join('')}</main>${recent()}<footer class="footer"><span>明细保留：3个月</span><span>图片存储：关闭</span><span>当前未决：${pending()} 项</span><span class="right">${F.date} ${F.now} · 演示 UTC+08:00 · UI v1.1</span></footer>${demo()}</div><section class="min-window"><div class="brand"><div class="brandmark">${ic('scan')}</div><h2>供包工作台 · ${F.station}</h2></div><h2>窗口空间不足，暂停新作业</h2><p>有效内容区至少需要 <strong>1280 × 680</strong>。请最大化窗口或由维护人员调整Windows显示设置；不通过缩小文字继续供包。</p><div class="notice"><b>当前业务上下文已保留</b><p class="mono">${active()?F.tote:'当前无活动箱'}</p><p>CAM0：${status(s.lanes[0])[1]}<br>CAM1：${status(s.lanes[1])[1]}<br>待核对 / 处理中：${pending()}项</p></div><p>已发请求不会因窗口变化而撤销。恢复有效窗口后须确认恢复入场，不重复放货。</p></section>`;renderLayer();$('#scene').onchange=e=>{history.replaceState(null,'','#'+e.target.value);reset(e.target.value);};$('#tote-form')?.addEventListener('submit',e=>{e.preventDefault();submitTote();});}
function open(type){restoreFocus=document.activeElement?.dataset?.action;s.drawer=type;s.page=null;s.modal=null;renderLayer();setTimeout(()=>$('#layer [data-close]')?.focus(),10);}
function close(){if(s.modal==='closing')return toast('关闭请求已提交，不能在本地取消WCS动作。');if(s.modal==='shortage'){s.session='Active';s.gate=true;}s.modal=null;s.drawer=null;render();if(restoreFocus)[...document.querySelectorAll('[data-action]')].find(e=>e.dataset.action===restoreFocus)?.focus();}
function shell(title,sub,body,footer='',wide=false){return `<div class="overlay"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${title}"><header class="drawer-header"><div><h2>${title}</h2><p>${sub}</p></div>${btn('','close','icon-btn',false,'close','data-close aria-label="关闭抽屉"')}</header><div class="drawer-body">${body}</div><footer class="drawer-footer">${footer||'<span class="hint">只读查看，不重发业务请求。</span>'+btn('返回工作台','close')}</footer></section></div>`;}
function filtered(){return s.records.filter(r=>r.date>=s.dateFrom&&r.date<=s.dateTo&&(!s.filter||[r.id,r.barcode,r.task,r.tote].some(v=>v.includes(s.filter)))&&(s.statusFilter==='all'||r.state===s.statusFilter)&&(s.laneFilter==='all'||'CAM'+r.channel===s.laneFilter));}
function recordsView(){const rs=filtered();let b=`<div class="notice blue">保留最近3个月明细。记录按业务作业聚合，发送尝试不是新Item。</div><form id="filter-form" class="filter-grid"><label>箱码 / 条码 / 任务 / 作业ID<input id="search" value="${esc(s.filter)}" placeholder="输入完整或部分标识"></label><label>处理结果<select id="result-filter">${[['all','全部结果'],['Accepted','WCS已接受'],['Rejected','已拒绝'],['OutcomeUnknown','待核对']].map(([v,n])=>`<option value="${v}" ${s.statusFilter===v?'selected':''}>${n}</option>`).join('')}</select></label><label>通道<select id="lane-filter">${['all','CAM0','CAM1'].map(v=>`<option value="${v}" ${s.laneFilter===v?'selected':''}>${v==='all'?'全部通道':v}</option>`).join('')}</select></label><button type="submit" class="primary">查询</button></form><div class="row between" style="margin-bottom:18px"><div class="row"><label class="hint">开始 <input id="date-from" type="date" value="${s.dateFrom}" form="filter-form"></label><label class="hint">结束 <input id="date-to" type="date" value="${s.dateTo}" form="filter-form"></label></div>${btn('导出当前结果','export','small',s.emptyMode!==null,'download')}</div>`;if(s.emptyMode==='loading')b+='<div class="empty"><h3>正在查询记录</h3><p>当前箱与通道状态不受影响。</p></div>';else if(s.emptyMode==='error')b+=`<div class="empty"><h3>记录查询失败</h3><p>读取失败不等于没有记录；不会清除业务事实。</p>${btn('重新查询','retryQuery','primary')}</div>`;else if(!rs.length)b+=`<div class="empty">${ic('search','lg')}<h3>${s.records.length?'未找到匹配记录':'尚无作业记录'}</h3><p>${s.records.length?'请调整查询条件；无匹配不代表没有业务记录。':'完成第一次业务后，这里将显示识别、校验与处理过程。'}</p>${btn('清除筛选','clearFilter')}</div>`;else b+=`<table class="table"><thead><tr><th>时间</th><th>通道</th><th>Item条码</th><th>作业ID</th><th>格口</th><th>接受/件</th><th>业务结果</th><th>发送次数</th><th>操作</th></tr></thead><tbody>${rows(rs)}</tbody></table><p class="hint">共${rs.length}次作业 · 本筛选WCS接受${rs.filter(r=>r.state==='Accepted').reduce((n,r)=>n+r.quantity,0)}件；重试和查询不重复计数。</p>`;return shell('作业记录','PAGE-06 · 业务作业与网络尝试分层追溯',b,'',true);}
function detailView(){const l=s.lanes.find(l=>l.operation===s.detail),r=s.records.find(r=>r.id===s.detail)||{id:l?.operation||'OP-005',barcode:l?.barcode||'—',channel:l?.id??1,state:l?.state||'Observed',quantity:0,task:l?.task||'—',slot:l?.slot||'—',wave:l?.wave||'—',time:l?.time||F.now,attempts:0};const id='REQ-DEMO-'+r.id.replace('OP-',''),good=r.state==='Accepted',bad=r.state==='Rejected',unknown=r.state==='OutcomeUnknown',special=r.id==='OP-004';const pre=['Observed','Idle','InvalidRead','UnpackRequired','UnpackCounting','AwaitingUnpackConfirm','AwaitingManualDispatch','ReadyForAutoDispatch'].includes(r.state);const stages=[[r.time,'相机观察已归属本次作业','CAM'+r.channel+' · 触发ACQ-'+r.id+'；同条码不等于同一次作业。']];if(bad)stages.push([r.time,'WCS校验拒绝',l?.reason||'非本波次；未取得可执行发车任务。']);else if(pre||r.state==='Validating')stages.push(['当前','尚无业务接受证据','不得补写校验通过、已发车或实体完成。']);else{stages.push([special?'14:31:57.214':r.time,'任务及发送意图已保存','当前任务快照与固定业务请求ID绑定；先持久化再发送。']);if(special)stages.push(['14:31:57.231','尝试01明确未交给网络','NotHandedToTransport：这是本例明确证据，不是所有网络错误的默认结论。']);stages.push([r.time,good?'收到明确业务接受回执':unknown?'等待超时 → 结果待核对':'等待业务结果',good?`仅原作业记入${r.quantity}件；实体离站未取得反馈。`:unknown?'WCS可能已处理，不判为拒绝，不自动重发。':'保存、发送、接受为不同事实。']);}const b=`<div class="notice ${good?'ok':bad?'error':'warn'}"><b>${good?'WCS已接受 · 不是实体完成':bad?'WCS已拒绝 · 不自动重试':unknown?'结果待核对 · 请勿重复放货':'尚无明确接受证据'}</b><br>${special?'一次业务作业，2次发送尝试，仅记入18件。':'只展示当前证据，查看详情不产生新请求。'}</div><h3 class="section-title">业务身份</h3><div class="facts"><div><div class="label">供包作业ID</div><div class="value mono">${r.id}</div></div><div><div class="label">来源通道 / 修订</div><div class="value">CAM${r.channel} / revision ${l?.revision||1}</div></div><div class="full"><div class="label">Item条码</div><div class="value mono">${esc(r.barcode)}</div></div><div><div class="label">周转箱</div><div class="value mono">${F.tote}</div></div><div><div class="label">Item波次</div><div class="value mono">${r.wave}</div></div><div><div class="label">分拨任务ID</div><div class="value mono">${r.task}</div></div><div><div class="label">业务请求ID</div><div class="value mono">${pre?'尚未创建发车请求':id}</div></div></div><h3 class="section-title">识别与处理时间线</h3><div class="timeline">${stages.map(([time,t,d])=>`<div class="timeline-item"><div class="timeline-time">${time}</div><div class="timeline-name">${t}</div><div class="timeline-desc">${esc(d)}</div></div>`).join('')}</div><h3 class="section-title">网络尝试（不是新增Item）</h3><table class="table"><thead><tr><th>尝试</th><th>原请求ID</th><th>技术事实</th><th>业务新增</th></tr></thead><tbody>${special?`<tr><td>01</td><td class="mono">${id}</td><td>明确未交付网络</td><td>0</td></tr><tr><td>02</td><td class="mono">${id}</td><td>明确业务接受</td><td>仅原作业入账</td></tr>`:`<tr><td>${r.attempts||'—'}</td><td class="mono">${pre?'尚未创建':id}</td><td>${unknown?'终态未取得':bad?'校验明确拒绝':pre?'未提交发车请求':'当前阶段见上方'}</td><td>没有第二次作业</td></tr>`}</tbody></table>${unknown?'<div class="notice warn" style="margin-top:20px">WCS查询接口尚未提供；不开放标记成功或直接重发。核对样例只允许由评审台注入。</div>':''}`;return shell('作业详情',r.id+' · CAM'+r.channel+' · 原业务与发送尝试分开追溯',b,`<span class="hint">所有身份与过程均为示例。</span>${btn('复制请求ID','copyRequest','small',pre,'copy')}`);}
function settingsView(){let b=`<div class="tabs">${btn('设备与连接','tabDevices',s.settingsTab==='devices'?'active':'')}${btn('维护配置','tabConfig',s.settingsTab==='config'?'active':'')}</div>`;if(s.settingsTab==='devices'){b+='<div class="notice blue" style="margin-top:18px">设备状态为只读展示。点击状态不会改变在线、AGV就位或发车许可。</div>';b+=[0,1].map(i=>`<section class="device-card"><div class="row between"><h3>CAM${i} · ${i?'右':'左'}通道</h3>${chip(s.camera[i]==='Ready'?'采集就绪':s.camera[i]==='Reconnecting'?'重连中':'未就绪',s.camera[i]==='Ready'?'ok':'error')}</div><div class="device-meta"><div class="muted">稳定标识<b class="mono">DEMO-CAMERA-${i}</b></div><div class="muted">型号 / SDK版本<b>未提供 · 待核验</b></div><div class="muted">最近可靠反馈<b class="mono">${s.camera[i]==='Ready'?F.now:'14:31:12'}</b></div><div class="muted">图像预览 / 留存<b>未启用 / 不存储图片</b></div></div></section>`).join('');b+=`<section class="device-card"><div class="row between"><h3>WCS通信及动作反馈</h3>${chip(s.wcs==='Ready'?'模拟链路就绪':'不可用',s.wcs==='Ready'?'ok':'error')}</div><div class="device-meta"><div class="muted">真实接口契约<b>未提供</b></div><div class="muted">幂等 / 查询能力<b>未核验；不自动重发</b></div><div class="muted">AGV就位 / 装载许可<b>D-05 / D-06 待确认</b></div><div class="muted">凭据<b>不会显示或写入诊断摘要</b></div></div></section><div class="row">${btn('导出诊断摘要','diagnostics','small',false,'download')}${btn('重连设备','noop','small',true,'lock')}</div><p class="hint">维护重连需要授权及现场前置条件。原型只在评审台注入恢复，不调用SDK。</p>`;}else{b+=`<div class="notice ${s.role==='maintenance'?'warn':'blue'}" style="margin-top:18px">${s.role==='maintenance'?'维护配置样例：仅暂存于页面内存，不写入设备或Windows配置。':'操作员只读。需维护授权、无活动箱且无未决请求，才能修改关键配置。'}</div><form id="config-form"><h3 class="section-title">站位与运行模式</h3><label class="setting-row"><span>物理供包台ID</span><input name="station" value="${esc(s.config.station)}" ${s.role!=='maintenance'?'disabled':''}></label><label class="setting-row"><span>楼层</span><select name="floor" ${s.role!=='maintenance'?'disabled':''}>${['1层','2层'].map(x=>`<option ${s.config.floor===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting-row"><span>登录方式</span><select name="auth" ${s.role!=='maintenance'?'disabled':''}>${['账号密码登录','已批准跳过登录'].map(x=>`<option ${s.config.auth===x?'selected':''}>${x}</option>`).join('')}</select></label><h3 class="section-title">尚未批准的策略（不可直接配置启用）</h3>${[['不足量发车','D-03 待确认；人工分支为候选'],['拆包扫描方向','D-04 待确认，生产禁用'],['动作联锁条件','D-05 待WCS/现场反馈'],['明细保留','3个月（自然月口径待确认）'],['图像保存','关闭；PRD明确无图片存储需求']].map(([k,v])=>`<label class="setting-row"><span>${k}</span><input readonly value="${v}"></label>`).join('')}${s.error?`<div class="notice error">${esc(s.error)}</div>`:''}<p class="hint">保存为新版本，下次受控启动生效；当前请求payload不改写。</p><button class="primary" type="submit" ${s.role!=='maintenance'?'disabled':''}>保存配置样例</button><span class="hint" style="margin-left:16px">当前演示版本 v${s.configVersion}</span></form>`;}return shell('设备与设置','PAGE-08 · 诊断只读 / 维护权限及配置为工程建议',b);}
function alarmsView(){const a=activeAlarm();let b=`<div class="notice warn">已读不等于恢复。不提供AGV强制发车、PLC复位或格口重分配。</div><div class="tabs" style="margin-top:16px">${btn('活动报警 · '+(a?1:0),'noop','active')}${btn('已恢复 · 1','recoveredAlarm')}</div>${a?`<section class="alarm-item"><div class="row between">${chip(a[0],'error')}${chip(s.alarmRead?'本地已读':'未读','warn')}</div><h3>${a[1]}</h3><p>${esc(a[2])}</p><div class="hint">来源：模拟${a[0]} · 首次14:32:02 · AL-DEMO-01</div><div class="row" style="margin-top:14px">${btn(s.alarmRead?'已标为本地已读':'标为本地已读','alarmRead','small',s.alarmRead)}${btn('查看关联作业','detail:OP-005','small')}</div></section>`:'<div class="empty"><h3>暂无活动报警</h3><p>仍须以各通道当前状态判断是否允许操作。</p></div>'}<section class="alarm-item" id="recovered-alarm">${chip('已恢复','ok')}<h3>CAM1连接短暂中断</h3><p>历史模拟事件，设备重新确认就绪；连接恢复不等于旧请求已接受。</p><span class="hint">发生14:20:11 · 恢复14:20:19</span></section><h3 class="section-title">处置原则</h3><div class="notice">先判断影响范围，再核对箱与Item。缺少权威状态时暂停新入场；报警原因与下一步持续显示。</div>`;return shell('报警与处置','PAGE-07 · 来源、作用域、已读与恢复分开',b,`<span class="hint">导出不含凭据、图片或无关文件。</span>${btn('导出诊断摘要','diagnostics','small',false,'download')}`);}
function modalShell(title,b,actions){return `<div class="overlay modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><span class="warn-text">${ic('warn','lg')}</span><h2 id="modal-title">${title}</h2></header><div class="modal-body">${b}</div><footer class="modal-footer">${actions}</footer></section></div>`;}
function modalView(){const cancel=btn('取消','close','',false,'','data-close');if(s.modal==='shortage')return modalShell('发现Item缺失，是否强制结束？',`<div class="row between" style="margin-bottom:18px"><div><div class="label">当前周转箱</div><b class="mono" style="font-size:21px">${F.tote}</b></div>${chip('WCS少货检查','warn')}</div><div class="shortage-count"><div><strong>缺失基础SKU数量</strong><div class="caption">来自WCS核对快照 CHECK-DEMO-7</div></div><div><b>2</b><span class="unit">件</span></div></div><table class="table"><thead><tr><th>SKU</th><th>缺失数量</th><th>单位</th></tr></thead><tbody><tr><td class="mono">WMS-K29401</td><td>2</td><td>件</td></tr></tbody></table><p class="hint">两通道均无在途请求。取消后可继续扫描；强制结束按少货事实提交WCS，不直接清空本地箱。</p><label class="check-label" style="min-height:44px"><input id="shortage-check" type="checkbox" ${s.check?'checked':''}><span>已检查周转箱与工位，确认未找到遗漏的2件Item。</span></label>`,btn('取消，继续供包','close','',false,'','data-close')+btn('确认强制结束','forceClose','danger-fill',!s.check));if(s.modal==='closing')return modalShell('正在结束周转箱',`<div class="notice blue"><b>WCS处理中，请勿扫描新箱</b><br>${F.tote}保留，只有明确TOTE_CLOSED后才重置。</div><p class="hint">关闭界面不等于取消远端关闭请求。</p>`,btn('正在提交WCS…','noop','primary',true));if(s.modal==='closeBlocked')return modalShell('当前不能结束供包',`<div class="notice warn">${s.session==='CloseUnknown'?'原关闭请求结果待核对。不能开新箱，也不能继续旧箱。':'两通道尚有草稿、拆包、在途或待核对作业，不能直接清屏。'}</div><div class="facts" style="margin-top:18px"><div><div class="label">CAM0</div><div class="value">${status(s.lanes[0])[1]}</div></div><div><div class="label">CAM1</div><div class="value">${status(s.lanes[1])[1]}</div></div></div><p class="hint">少货强制结束不能绕过结果不明、实体核对或未完成拆包。</p>`,btn('返回处理当前作业','close','primary',false,'','data-close'));if(s.modal==='clear'){const l=s.lanes[s.clearLane];return modalShell('清空当前扫描计数？',`<p>仅废弃 <b>CAM${l.id} / ${l.operation} / v${l.revision}</b> 的未提交草稿。</p><div class="notice warn">有效计数${l.count}件将重新计数。既有WCS接受量、另一通道与历史不清除。</div><p class="hint">若有远端预留，生产实现必须先核验释放条件；本例只有无副作用草稿。</p>`,cancel+btn('清空并重新计数','confirmClear','primary'));}if(s.modal==='pause')return modalShell('暂停软件新入场？','<div class="notice warn">暂停后不再创建新的可执行供包作业；已发送WCS请求仍会继续核对。</div><p>此按钮不控制安全急停，也不保证AGV停止。</p>',cancel+btn('暂停新入场','confirmPause','primary'));return modalShell('登出前需要保护当前作业','<div class="notice warn">仍有活动箱或未决作业，不能直接清除身份与业务上下文。</div><p>请先完成或核对当前作业；换班继承与真实登出契约尚未确认。</p>',btn('返回当前作业','close','primary',false,'','data-close'));}
function entry(){const login=s.page==='login',recovery=s.page==='recovering';let b;if(login)b=`<form class="entry-card login" id="login-form"><h2>登录供包工作台</h2><p>身份通过WCS验证。请勿输入真实凭据。</p><label>操作员账号<input id="username" autocomplete="off" value="operator" placeholder="演示账号operator"></label><label>密码<input id="password" type="password" autocomplete="off" placeholder="输入任意非空演示密码"></label>${s.scene==='loginRejected'?'<div class="notice error" style="margin-top:20px">认证拒绝：账号或密码不正确。请核对后提交。</div>':s.scene==='loginNetwork'?'<div class="notice warn" style="margin-top:20px">WCS不可用，无法验证身份。这不是密码错误。</div>':''}<button class="primary" type="submit" ${s.busy?'disabled':''}>${s.busy?'正在验证身份…':'登录'}</button><p class="hint">账号密码仅在页面内存使用，不发送网络请求。</p></form>`;else b=`<div class="entry-card"><h2>${recovery?'恢复核对中':'正在进行启动自检'}</h2><p>${recovery?'先恢复旧箱与未决请求，再开放新作业。':'连接成功不等于采集就绪，各项事实独立验证。'}</p>${(recovery?[['本地业务记录','活动箱 TC-2026-0091','已读取','ok'],['原始请求身份','REQ-DEMO-005，不创建新ID','已保留','ok'],['WCS业务结果','可能已生效，等待权威证据','待核对','warn'],['设备及实体状态','重新验证就位、装载与任务','未确认','warn'],['新作业入场','所有关联事实收敛前暂停','已阻止','']]:[['配置与存储','配置版本与数据schema','通过','ok'],['历史恢复清单','旧请求尚未核对完毕','检查中','blue'],['CAM0','建立连接及注册结果','连接中','blue'],['CAM1','已连接，尚未采集就绪','未就绪','warn'],['WCS及认证','真实接口契约待提供','待核验','warn']]).map(([t,d,v,c])=>`<div class="check-item">${ic(c==='ok'?'checkCircle':'clock')}<div><b>${t}</b><div class="hint">${d}</div></div>${chip(v,c)}</div>`).join('')}<div class="notice warn" style="margin-top:20px">此为界面设计，未运行真实SDK或WCS查询。未决结果不得自动重发。</div><div class="row between" style="margin-top:20px">${btn('查看诊断摘要','diagnostics')}${btn(recovery?'等待核对完成':'自检尚未完成','noop','',true)}</div></div>`;return `<section class="fullpage"><header class="entry-header"><div class="brand"><div class="brandmark">${ic('scan')}</div><h1>供包工作台</h1><span class="hint">ST-01 · 1层</span></div>${chip('交互评审 · 示例数据','blue')}</header><main class="entry-center">${b}</main><footer class="entry-foot">${login?'登录跳过只能由已批准配置控制，不提供临时跳过验证按钮。':'保留旧箱与原始请求；演示入口在底部控制台。'}</footer></section>`;}
function components(){const sw=[['中性底色','#F1F4F7'],['主操作','#205FCE'],['明确接受','#147450'],['待核对','#895509'],['明确拒绝','#B52F38']];return `<section class="component-page"><div class="row between"><div><h1>供包工作站 · 组件与视觉规范</h1><span class="hint">SS-UI-VIS-001 · 中性界面 / 统一语义 / 不以颜色代替文字</span></div>${btn('返回工作台','backNormal')}</div><div class="component-grid"><section class="component-box"><h2>01 / 颜色与状态</h2><div class="swatch-row">${sw.map(([n,c])=>`<div><div class="swatch-color" style="background:${c}"></div><div class="caption">${n}</div><div class="caption mono">${c}</div></div>`).join('')}</div><div class="row wrap" style="margin:20px 0">${chip('WCS已接受','ok')}${chip('结果待核对','warn')}${chip('已拒绝','error')}${chip('处理中','blue')}</div><div class="notice warn"><b>异常持续可见</b><br>原因 + 影响范围 + 下一步，不统一写成“失败，请重试”。</div></section><section class="component-box"><h2>02 / 字体与数字</h2><div class="result-title">WCS已接受 <span class="caption">结果29 / 紧凑23</span></div><div class="barcode">06901068034919</div><div class="hint">条码27 / 紧凑23 · 等宽，保留前导零与完整文本</div><p>正文16：当前Item需要人工确认</p><div class="hint">标签14 / 紧凑12；辅助12–13不承担关键指令。<br>Windows：Microsoft YaHei UI / Microsoft YaHei / Segoe UI<br>等宽：Consolas / Cascadia Mono；截图使用Linux可用字体。</div></section><section class="component-box"><h2>03 / 按钮八态 · 主操作52 / 紧凑48</h2><div class="samples">${btn('默认','sample','primary')}${btn('悬停','sample','primary force-hover')}${btn('按下','sample','primary force-press')}${btn('键盘聚焦','sample','primary force-focus')}${btn('条件不足','noop','primary',true)}${btn('正在提交…','noop','primary',true)}${btn('已接受','sample','',false,'checkCircle')}${btn('查看拒绝原因','sample','danger',false,'warn')}</div><p class="hint">执行期间锁定同作业版本。结果在通道区显示，不以点击当作成功。</p><div class="notice">Tab依可见顺序移动；Esc只关闭可取消视图，不清空业务。Enter不作为全局发车键。</div></section><section class="component-box"><h2>04 / 输入、尺寸与边界</h2><div class="label">周转箱条码 · 唯一常规扫码枪输入</div><div class="row" style="margin-top:8px"><input value="TC-2026-0091" readonly style="flex:1"><input value="非本层箱" aria-invalid="true" readonly style="width:155px"></div><p class="hint">8px间距基准；页面边距24，列间20；面板圆角10，按钮7，边框1。</p><div class="notice blue">业务触控目标≥44×44，主操作48–52高。线性图标20px且配中文；禁用原因邻近按钮，不藏在悬停提示。</div></section><section class="component-box"><h2>05 / 追溯表格</h2><table class="table"><thead><tr><th>作业ID</th><th>WCS结果</th><th>发送尝试</th><th>接受/件</th></tr></thead><tbody><tr><td class="mono">OP-004</td><td>${chip('已接受','ok')}</td><td>2次</td><td>18</td></tr></tbody></table><p class="hint">作业与网络尝试分层。带操作行≥44高，标识符不转普通数字。</p></section><section class="component-box"><h2>06 / 布局适配与提示声</h2><div class="row">${btn('试听接受','sound:accepted','small',false,'volume')}${btn('试听拒绝','sound:rejected','small',false,'volume')}${btn('试听拆包','sound:split','small',false,'volume')}</div><p class="hint">三个不同节奏的合成样例；点击后启动，不循环。需现场听审。</p><div class="notice">1920×1080基准；1536×864、1366×768、1280×720采用紧凑重排，不整体缩放。小于1280×680显示保护界面。</div></section></div></section>`;}
function renderLayer(){const html=s.page==='components'?components():s.page?entry():s.modal?modalView():s.drawer==='records'?recordsView():s.drawer==='detail'?detailView():s.drawer==='settings'?settingsView():s.drawer==='alarms'?alarmsView():'';$('#layer').innerHTML=html;[...document.querySelectorAll('.app > *:not(.demo-bar)')].forEach(e=>e.inert=!!html);$('#shortage-check')?.addEventListener('change',e=>{s.check=e.target.checked;$('[data-action="forceClose"]').disabled=!s.check;});$('#filter-form')?.addEventListener('submit',e=>{e.preventDefault();const from=$('#date-from').value,to=$('#date-to').value;if(!from||!to||from>to)return toast('开始日期不能晚于结束日期。');Object.assign(s,{filter:$('#search').value,statusFilter:$('#result-filter').value,laneFilter:$('#lane-filter').value,dateFrom:from,dateTo:to,emptyMode:'loading'});renderLayer();later(()=>{s.emptyMode=null;renderLayer();},450);});$('#config-form')?.addEventListener('submit',e=>{e.preventDefault();if(s.role!=='maintenance'||active()||pending())return toast('需要维护授权、无活动箱及无未决请求。');const f=new FormData(e.target),station=String(f.get('station'));if(!/^ST-\d{2}$/.test(station)){s.error='供包台ID格式错误：示例格式为ST-两位数字；实际规则待确认。';return renderLayer();}s.error='';s.config={station,floor:f.get('floor'),auth:f.get('auth')};s.configVersion++;s.audit.push({command:'SaveConfiguration',version:s.configVersion});renderLayer();toast('配置样例已暂存为v'+s.configVersion+'，仅内存；下次受控启动生效。');});$('#login-form')?.addEventListener('submit',e=>{e.preventDefault();const u=$('#username').value,p=$('#password').value;if(!u||!p)return toast('请输入非空演示账号和密码，不要使用真实凭据。');if(s.scene==='loginNetwork')return toast('WCS不可用，无法验证身份，不视为密码错误。');s.busy=true;renderLayer();later(()=>{if(u==='reject'){s.busy=false;s.scene='loginRejected';renderLayer();}else{reset('waiting');toast('模拟身份验证通过；未发送真实认证请求。');}},600);});}
function toast(t){clearTimeout(toastTimer);$('#toast').className='toast';$('#toast').textContent=t;toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},3000);}
function sound(kind,key){if(s.sounds.includes(key))return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume();const tones={accepted:[660,880],rejected:[330,260,330],split:[520,520,780]}[kind],t=audio.currentTime;tones.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=hz;g.gain.setValueAtTime(0,t+i*.19);g.gain.linearRampToValueAtTime(.06,t+i*.19+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.19+.15);o.connect(g);g.connect(audio.destination);o.start(t+i*.19);o.stop(t+i*.19+.16);});s.sounds.push(key);}catch(e){toast('浏览器未能播放提示声，需现场验证。');}}
function copyText(text){const f=()=>{const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;left:-9999px';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制完整标识。':'浏览器禁止复制，请选择完整条码文本复制。');};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('已复制完整标识。')).catch(f);else f();}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function submitTote(){if(active()||s.session==='ValidatingTote')return;const value=$('#tote-input').value;if(!value)return toast('请先扫描周转箱。');s.toteInput=value;s.session='ValidatingTote';render();later(()=>{if(value!==F.tote){s.session='ToteRejected';render();toast('演示只接受TC-2026-0091；不是实际WCS规则。');}else{s.session='Active';s.gate=true;s.lanes.forEach(l=>l.state='Idle');render();$('#lane0').tabIndex=-1;$('#lane0').focus();toast('模拟箱校验通过，Item仍按相机来源路由。');}},700);}
function dispatch(i){const l=s.lanes[i];if(!permitted(l))return toast('当前条件不允许发车；未创建新请求。');s.audit.push({command:'SubmitManualDispatch',operation:l.operation,revision:l.revision});l.state='DispatchQueued';record(l);render();later(()=>{l.state='DispatchPending';const r=s.records.find(r=>r.id===l.operation);r.state='DispatchPending';r.attempts=1;render();later(()=>{l.state='Accepted';accept(l);sound('accepted',l.operation+':'+l.revision);render();toast('模拟WCS明确接受，不表示实体动作完成。');},850);},250);}
function finishClose(){s.busy=true;s.session='Closing';s.modal='closing';render();later(()=>{s.busy=false;s.modal=null;s.session='AwaitingTote';s.sessionId++;s.lanes.forEach(l=>l.state='Idle');s.gate=true;s.toteInput='';render();$('#tote-input')?.focus();toast('模拟WCS明确关闭；原箱历史保留。');},1000);}
function action(a){const[cmd,arg]=a.split(':');if((innerWidth<1280||innerHeight<680)&&!['reset','backNormal'].includes(cmd))return toast('窗口空间不足，业务操作已阻止。');switch(cmd){case'noop':return;case'sample':return toast('仅组件行为样例，不提交业务命令。');case'records':s.emptyMode=null;open('records');return;case'settings':s.settingsTab='devices';open('settings');return;case'alarms':open('alarms');return;case'detail':s.detail=arg;open('detail');return;case'close':close();return;case'copy':copyText(s.lanes[+arg].barcode);return;case'copyRequest':copyText('REQ-DEMO-'+s.detail.replace('OP-',''));return;case'tabDevices':s.settingsTab='devices';renderLayer();return;case'tabConfig':s.settingsTab='config';renderLayer();return;case'dispatch':dispatch(+arg);return;case'clear':if(!canClear(s.lanes[+arg]))return toast('当前作业不能安全清空。');s.clearLane=+arg;s.modal='clear';renderLayer();setTimeout(()=>$('#layer [data-close]')?.focus(),10);return;case'confirmClear':{const l=s.lanes[s.clearLane];if(!canClear(l))return;l.revision++;l.count=0;l.state=s.demoSplit?'UnpackCounting':'Idle';s.audit.push({command:'ClearAndRescan',operation:l.operation,revision:l.revision});s.modal=null;render();return;}case'splitConfirm':{const l=s.lanes[+arg];if(!s.demoSplit||l.count!==18||!s.gate)return;l.state='AwaitingManualDispatch';l.supply=18;s.audit.push({command:'ConfirmUnpackDemo',retained:18,removed:12,operation:l.operation});render();toast('候选：保留18件、移除12件；真实拆包策略待批准。');return;}case'end':if(!active())return;if(s.session==='CloseUnknown'||unfinished()){s.modal='closeBlocked';renderLayer();return;}s.session='ClosingCheck';s.gate=false;render();later(()=>{if(s.noShortage)finishClose();else{s.session='AwaitingShortageDecision';s.modal='shortage';render();setTimeout(()=>$('#layer [data-close]')?.focus(),10);}},500);return;case'forceClose':if(!s.check||s.busy||unfinished())return;s.audit.push({command:'ConfirmForcedClose',missing:2,session:s.sessionId});finishClose();return;case'pause':if(s.session!=='Active')return;s.modal='pause';renderLayer();return;case'confirmPause':s.session='Paused';s.gate=false;s.modal=null;render();return;case'resume':if(!s.store||s.wcs!=='Ready'||s.camera.some(x=>x!=='Ready')||pending())return toast('依赖或未决结果尚未收敛。');s.session='Active';s.gate=true;s.viewportPaused=false;render();toast('恢复新入场，不重发旧请求。');return;case'logout':if(active()||pending()){s.modal='logout';renderLayer();}else reset('login');return;case'clearFilter':Object.assign(s,{filter:'',statusFilter:'all',laneFilter:'all',dateFrom:F.date,dateTo:F.date,emptyMode:null});renderLayer();return;case'retryQuery':s.emptyMode='loading';renderLayer();later(()=>{s.emptyMode=null;renderLayer();},500);return;case'export':if(s.emptyMode)return;download('供包作业记录_示例.json',{notice:'仅模拟数据；标识为字符串，保留前导零',records:filtered()});toast('已导出当前筛选示例JSON。');return;case'diagnostics':download('供包诊断摘要_示例.json',{mode:'SimulationOnly',station:F.station,camera:s.camera,wcs:s.wcs,session:s.session,unresolved:pending(),imageStorage:false,credentials:'excluded',audit:s.audit});toast('已导出模拟诊断摘要，不含凭据和图片。');return;case'alarmRead':s.alarmRead=true;renderLayer();toast('只标为本地已读，未恢复故障。');return;case'recoveredAlarm':$('#recovered-alarm')?.scrollIntoView({block:'center'});return;case'sound':sound(arg,'preview:'+arg+':'+Date.now());toast('已触发合成样例；仍需现场听审。');return;case'reset':reset(s.scene);return;case'backNormal':reset('normal');return;
 // Explicit review-only injection points, not operator commands.
 case'demoRead':{if(!active())return toast('请先在专用输入框校验TC-2026-0091。');if(!s.gate)return toast('入场受阻，未创建新作业。');if(s.demoSplit)return action('demoCount');const i=s.lanes.findIndex(l=>l.state==='Idle');if(i<0)return toast('通道仍有作业或待现场复位；从等待扫箱场景演示新作业。');let l=s.lanes[i];Object.assign(l,{operation:'OP-DEMO-'+s.nextId++,state:'Observed',barcode:'06901068034919',sku:'—',task:'—',slot:'—',wave:'—',p:null,d:null,supply:null});render();later(()=>{l.state='Validating';render();later(()=>{Object.assign(l,{state:'AwaitingManualDispatch',sku:'WMS-K29401',task:'12345500990',slot:'029',wave:F.wave,p:12,d:18,supply:12});render();},600);},300);return;}
 case'demoCount':{const l=s.lanes[1];if(!s.demoSplit||l.state!=='UnpackCounting')return;l.count=Math.min(18,l.count+1);if(l.count===18)l.state='AwaitingUnpackConfirm';render();return;}case'demoPermit':if(s.lanes[1].state==='ReadyForAutoDispatch'){s.lanes[1].state='AwaitingManualDispatch';dispatch(1);}return;case'demoResolve':{const l=s.lanes[1];if(l.state!=='OutcomeUnknown')return;l.state='Accepted';accept(l);s.session='Paused';s.gate=false;s.scene='recovered';s.drawer=null;render();toast('已注入模拟权威结果；没有重发，仍需恢复入场。');return;}case'demoRecover':reset('recovered');return;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action);});
document.addEventListener('keydown',e=>{const d=$('#layer [role="dialog"]');if(e.key==='Escape'&&d){e.preventDefault();close();}if(e.key==='Tab'&&d){const es=[...d.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(e=>e.getClientRects().length),first=es[0],last=es.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(innerWidth<1280||innerHeight<680){s.viewportPaused=true;s.gate=false;}else if(s.viewportPaused&&s.session==='Active')s.session='Paused';render();},70);});
window.SS_DEMO={setScene:reset,getState:()=>structuredClone(s),action,scenes:SCENES};reset(SCENES.some(([v])=>v===location.hash.slice(1))?location.hash.slice(1):'normal');
